(() => {'use strict';const root=document.getElementById('verification-result'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));(async()=>{try{const token=location.pathname.slice('/verify/'.length);if(!/^[a-f0-9]{48}$/.test(token))throw Error('No credential was found. Check the verification link.');const r=await fetch('/api/academy/verify/'+token,{cache:'no-store'}),a=await r.json();if(!r.ok)throw Error(a.error||'The verification register is unavailable.');root.innerHTML=`<span class="status ${a.status==='Active'?'good':'warm'}">${esc(a.status)}</span><h2 style="margin-top:20px">${esc(a.name)}</h2><p>${esc(a.course)}</p><p class="small muted">${esc(a.id)} · Issued ${esc(new Date(a.issuedAt).toLocaleDateString())}</p><p>${esc(a.scope)}</p>${a.reason?`<div class="notice error">${esc(a.reason)}</div>`:''}<p class="credential-meta">Evidence digest: ${esc(a.evidenceHash)}</p>`}catch(error){root.replaceChildren();const p=document.createElement('p');p.textContent=error.message;root.append(p)}})()})();
